const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  var phoenix = ee.Geometry.Point([-112.0740, 33.4484]);  // Phoenix, AZ
  var startDate = '2017-06-15';
  var endDate = '2017-06-22';  // exclusive, so covers through June 21
  var thresholdK = 316.48;  // 110°F in Kelvin

  // 2. Data Acquisition - MODIS LST
  var modisTerra = ee.ImageCollection('MODIS/061/MOD11A1')
    .filterDate(startDate, endDate)
    .filterBounds(phoenix);
  var modisAqua = ee.ImageCollection('MODIS/061/MYD11A1')
    .filterDate(startDate, endDate)
    .filterBounds(phoenix);
  var modis = modisTerra.merge(modisAqua);

  // Check initial collection size
  var modisSize = modis.size().getInfo();
  console.log('MODIS images (Terra+Aqua):', modisSize);

  var collection;
  if (modisSize > 0) {
    collection = modis;
  } else {
    // Fallback to ERA5-Land for air temperature
    console.log('No MODIS images, trying ERA5-Land.');
    var era5 = ee.ImageCollection('ECMWF/ERA5_LAND/HOURLY')
      .filterDate(startDate, endDate)
      .filterBounds(phoenix)
      .select('temperature_2m');  // in Kelvin
    var era5Size = era5.size().getInfo();
    console.log('ERA5-Land hourly images:', era5Size);
    if (era5Size === 0) {
      console.log('<answer>C1</answer>');
      return;
    }
    // Aggregate hourly to daily max, then overall max
    // Create daily composite by grouping by day
    var days = ee.List.sequence(0, 6);  // June 15-21 is 7 days
    var dailyMax = ee.ImageCollection.fromImages(
      days.map(function(dayOffset) {
        var start = ee.Date(startDate).advance(dayOffset, 'day');
        var end = start.advance(1, 'day');
        var daily = era5.filterDate(start, end);
        return daily.max().set('system:time_start', start.millis());
      })
    );
    collection = dailyMax;
  }

  // 3. Processing - Mask poor quality for MODIS
  if (collection === modis) {
    // Function to scale and mask MODIS LST
    var maskModis = function(image) {
      var lst = image.select('LST_Day_1km').multiply(0.02);  // scale to Kelvin
      var qc = image.select('QC_Day');
      // Bits 0-1: 00 = good quality
      var mask = qc.bitwiseAnd(3).eq(0);
      return lst.updateMask(mask).copyProperties(image, ['system:time_start']);
    };
    collection = collection.map(maskModis);
  }

  // Create max temperature composite
  var maxTempImg = collection.max();

  // 4. Calculate statistics at point
  var stats = maxTempImg.reduceRegion({
    reducer: ee.Reducer.count().combine({
      reducer2: ee.Reducer.max(),
      sharedInputs: true
    }),
    geometry: phoenix,
    scale: 1000,
    maxPixels: 1e9
  });

  var pixelCount = stats.get('count').getInfo();
  var maxTemp = stats.get('max').getInfo();

  console.log('Valid pixels:', pixelCount);
  console.log('Max temperature (K):', maxTemp);
  if (maxTemp !== null) {
    var maxTempF = (maxTemp - 273.15) * 9/5 + 32;
    console.log('Max temperature (°F):', maxTempF.toFixed(2));
  }

  // 5. Validation & Final Answer
  if (pixelCount === 0) {
    console.log('<answer>C2</answer>');
  } else if (maxTemp === null || isNaN(maxTemp) || maxTemp < 200 || maxTemp > 400) {
    console.log('<answer>C3</answer>');
  } else if (maxTemp >= thresholdK) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
